function campaign_admin_row(PDO $pdo,int $id): ?array { $s=$pdo->prepare('SELECT * FROM email_campaigns WHERE id=:id LIMIT 1');$s->execute([':id'=>$id]);return $s->fetch()?:null; }
function campaign_admin_redirect(int $id,string $message): void { $_SESSION['flash_success']=$message;header('Location: campaigns.php?view=edit&id='.$id);exit; }
function campaign_template_redirect(int $id,string $message): void { $_SESSION['flash_success']=$message;header('Location: campaigns.php?view=template_edit&template_id='.$id);exit; }
function campaign_admin_back_link(array $campaign): array
{
    $type=(string)($campaign['campaign_type']??'');
    if(in_array($type,['event_entries_open_members','event_entries_open_non_members','event_entries_closing','weekly_ride_notice'],true))return ['campaigns.php?tab=automatic','Back to automatic campaigns'];
    if($type==='ride_notes'&&!empty($campaign['event_id']))return ['ride_notes.php?event_id='.(int)$campaign['event_id'],'Back to Ride Notes'];
    return ['campaigns.php?tab=manual','Back to manual campaigns'];
}
function campaign_template_back_link(array $template): array
{
    if(in_array((string)($template['template_key']??''),['entries_open_members','entries_open_non_members','entries_closing','weekly_ride_notice'],true))return ['campaigns.php?tab=automatic','Back to automatic campaigns'];
    return ['campaigns.php?view=templates','Back to templates'];
}
function campaign_admin_send_limited_test(PDO $pdo,array $campaign,int $userId): array
{
    $userStmt=$pdo->prepare("SELECT u.id,u.email,u.first_name,u.last_name FROM users u WHERE u.id=:id AND (u.is_tester=1 OR LOWER(u.email) LIKE '%@truska.com') LIMIT 1");
    $userStmt->execute([':id'=>$userId]);$user=$userStmt->fetch()?:null;
    if(!$user||!filter_var((string)$user['email'],FILTER_VALIDATE_EMAIL))return ['ok'=>false,'message'=>'Choose a valid tester or @truska.com account.'];

    $settings=getSiteSettings($pdo);$base=emailCampaignBaseUrl($settings);$year=(int)($campaign['membership_year']??date('Y'));
    ensureMembershipTables($pdo);
    $personStmt=$pdo->prepare("SELECT p.id,p.member_number FROM people p LEFT JOIN membership_purchases mp ON mp.member_id=p.id AND mp.membership_year=:year AND mp.status<>'expired' WHERE p.owner_user_id=:user AND p.is_archived=0 ORDER BY (mp.id IS NOT NULL) DESC,p.id LIMIT 1");
    $personStmt->execute([':year'=>$year,':user'=>$userId]);$person=$personStmt->fetch()?:[];
    $first=trim((string)($user['first_name']??''));$last=trim((string)($user['last_name']??''));$email=strtolower(trim((string)$user['email']));
    $merge=array_merge(emailCampaignEventMerge($pdo,(int)($campaign['event_id']??0),$base),[
        'campaign_name'=>(string)$campaign['name'],'first_name'=>$first,'last_name'=>$last,'full_name'=>trim($first.' '.$last),
        'email'=>$email,'member_number'=>(string)($person['member_number']??''),'membership_year'=>(string)$year,
        'current_date'=>emailCampaignLocalNow()->format('j F Y'),'membership_url'=>$base.'/memberships','logbook_url'=>$base.'/logbooks',
        'message'=>'This is limited test content.','_user_id'=>$userId,'_person_id'=>(int)($person['id']??0),'_address_source'=>'account',
    ]);
    $tracking=sha1(random_bytes(32));$unsubscribe=sha1(random_bytes(32));
    $insert=$pdo->prepare("INSERT INTO email_campaign_limited_tests (campaign_id,user_id,person_id,email,category,merge_json,tracking_token,unsubscribe_token) VALUES (:campaign,:user,:person,:email,:category,:merge,:tracking,:unsubscribe)");
    $insert->execute([':campaign'=>(int)$campaign['id'],':user'=>$userId,':person'=>(int)($person['id']??0)?:null,':email'=>$email,':category'=>(string)$campaign['category'],':merge'=>json_encode($merge,JSON_UNESCAPED_SLASHES),':tracking'=>$tracking,':unsubscribe'=>$unsubscribe]);
    $limitedId=(int)$pdo->lastInsertId();$recipient=['merge_json'=>json_encode($merge,JSON_UNESCAPED_SLASHES),'tracking_token'=>$tracking,'unsubscribe_token'=>$unsubscribe];
    $payload=emailCampaignRenderRecipient($campaign,$recipient,$settings);$emailSettings=getEmailSettings($pdo);$beforeLogId=(int)$pdo->query('SELECT COALESCE(MAX(id),0) FROM email_log')->fetchColumn();
    $ok=send_logged_email($pdo,$email,subject_with_prefix($emailSettings,$payload['subject']),wrap_user_email_html($settings,$emailSettings,$payload['html'],$payload['after_footer_html']),wrap_user_email_text($settings,$emailSettings,$payload['text'],$payload['after_footer_text']),['kind'=>'campaign_limited_test','campaign_id'=>(int)$campaign['id'],'limited_test_id'=>$limitedId]);
    $logStmt=$pdo->prepare('SELECT id FROM email_log WHERE id>:after_id AND meta_json LIKE :marker ORDER BY id DESC LIMIT 1');$logStmt->execute([':after_id'=>$beforeLogId,':marker'=>'%"limited_test_id":'.$limitedId.'%']);$logId=(int)($logStmt->fetchColumn()?:0);
    $pdo->prepare('UPDATE email_campaign_limited_tests SET status=:status,email_log_id=:log,sent_at=IF(:sent=1,NOW(),NULL) WHERE id=:id')->execute([':status'=>$ok?'sent':'failed',':log'=>$logId?:null,':sent'=>$ok?1:0,':id'=>$limitedId]);
    return ['ok'=>$ok,'message'=>$ok?'Limited test sent to '.$email.'.':'Limited test was not sent. Check the email log and delivery safety settings.'];
}

function campaign_admin_send_template_test(PDO $pdo, array $template, array $currentUser): array
{
    $email = strtolower(trim((string)($currentUser['email'] ?? '')));
    if (!filter_var($email, FILTER_VALIDATE_EMAIL)) return ['ok' => false, 'message' => 'Your administrator account needs a valid email address before a test can be sent.'];
    $eventStmt = $pdo->query("SELECT id FROM events WHERE status='published' AND event_date >= CURDATE() ORDER BY event_date ASC, id ASC LIMIT 1");
    $eventId = (int)($eventStmt->fetchColumn() ?: 0);
    if ($eventId <= 0) return ['ok' => false, 'message' => 'There is no upcoming published event available for this test.'];
    $settings = getSiteSettings($pdo); $base = emailCampaignBaseUrl($settings);
    $campaign = array_merge($template, ['name' => (string)$template['name'], 'membership_year' => date('Y')]);
    if ((string)($template['template_key'] ?? '') === 'weekly_ride_notice') {
        $notice = weeklyRideNoticeContent($pdo, $base);
        $campaign['html_template'] = $notice['html'];
        $campaign['text_template'] = $notice['text'];
    }
    $merge = array_merge(emailCampaignEventMerge($pdo, $eventId, $base), [
        'campaign_name' => (string)$template['name'], 'first_name' => (string)($currentUser['first_name'] ?? 'Test'), 'last_name' => (string)($currentUser['last_name'] ?? ''),
        'full_name' => trim((string)($currentUser['first_name'] ?? '') . ' ' . (string)($currentUser['last_name'] ?? '')), 'email' => $email,
        'member_number' => 'TEST', 'membership_year' => date('Y'), 'current_date' => emailCampaignLocalNow()->format('j F Y'),
        'membership_url' => $base . '/memberships', 'logbook_url' => $base . '/logbooks', 'message' => 'This is a template test using the next upcoming event.',
    ]);
    $recipient = ['merge_json' => json_encode($merge, JSON_UNESCAPED_SLASHES), 'tracking_token' => sha1(random_bytes(32)), 'unsubscribe_token' => sha1(random_bytes(32))];
    $payload = emailCampaignRenderRecipient($campaign, $recipient, $settings); $emailSettings = getEmailSettings($pdo);
    $ok = send_logged_email($pdo, $email, subject_with_prefix($emailSettings, $payload['subject']), wrap_user_email_html($settings, $emailSettings, $payload['html'], $payload['after_footer_html']), wrap_user_email_text($settings, $emailSettings, $payload['text'], $payload['after_footer_text']), ['kind' => 'campaign_template_test', 'template_id' => (int)$template['id'], 'event_id' => $eventId, 'admin_user_id' => (int)($currentUser['id'] ?? 0)]);
    return ['ok' => $ok, 'message' => $ok ? 'Template test sent to ' . $email . ' using the next upcoming event.' : 'Template test was not sent. Check the email log and delivery safety settings.'];
}

if($_SERVER['REQUEST_METHOD']==='POST'){
