<div class="card-soft p-4"><div class="table-responsive"><table class="table align-middle"><thead><tr><th>Campaign</th><th>Audience</th><th>Status</th><th>Scheduled (UK)</th><th>Delivery</th><th></th></tr></thead><tbody><?php if(!$rows): ?><tr><td colspan="6" class="text-muted">No campaigns yet.</td></tr><?php endif; ?><?php foreach($rows as $row): ?><tr><td><strong><?php echo h((string)$row['name']); ?></strong><?php if($row['event_title']): ?><div class="small text-muted"><?php echo h((string)$row['event_title']); ?></div><?php endif; ?></td><td><?php echo h(emailCampaignPresets()[$row['audience_preset']]??(string)$row['audience_preset']); ?></td><td><?php echo h(ucfirst((string)$row['status'])); ?></td><td><?php echo $row['scheduled_at']?h(date('d M Y H:i',strtotime((string)$row['scheduled_at']))):'—'; ?></td><td><?php echo (int)$row['sent_count']; ?>/<?php echo (int)$row['recipient_count']; ?> sent · <?php echo (int)$row['opened_count']; ?> opened</td><td><a class="btn btn-sm btn-outline-secondary" href="campaigns.php?view=edit&amp;id=<?php echo (int)$row['id']; ?>">Open</a></td></tr><?php endforeach; ?></tbody></table></div></div>
